const wrap=(ctx,value,width)=>{const lines=[];let line='';for(const word of value.split(/\s+/)){const next=(line+' '+word).trim();if(ctx.measureText(next).width>width&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);return lines;};
