async function rasterPDF(out,blob,paper,name){const {loadScript}=await import('../extras.mjs'),{PDFDocument}=await loadScript('./assets/vendor/pdf-lib.min.js','PDFLib'),doc=await PDFDocument.create(),img=await doc.embedPng(await blob.arrayBuffer()),size=paperMetrics(paper).points,page=doc.addPage(size);page.drawImage(img,{x:0,y:0,width:size[0],height:size[1]});return new Blob([await doc.save()],{type:'application/pdf'});}
function addPDF(out,blob,paper,name){const b=document.createElement('button');b.type='button';b.className='btn secondary';b.textContent='Download PDF';b.onclick=async()=>{b.disabled=true;try{const pdf=await rasterPDF(out,blob,paper,name);if(b.isConnected)download(pdf,name+'.pdf');}catch(ex){if(b.isConnected)out.insertAdjacentHTML('beforeend','<p class="form-note">'+e(ex.message)+'</p>');}finally{if(b.isConnected)b.disabled=false;}};out.querySelector('.result-actions').append(b);}
export function setupVisualPlus(tool,mount,out){if(tool.id==='signature-maker')return signature(mount,out);if(tool.id==='text-3d')return textPoster(mount,out);return photoTool(tool,mount,out);}
function signature(mount,out){let strokes=[],current,release=()=>{};mount.innerHTML='<h2>A little personal mark.</h2><p class="form-note">Draw with your mouse, pen or finger. Nothing is saved automatically.</p><canvas class="signature-canvas" width="1000" height="340" aria-label="Signature drawing area"></canvas><p class="form-note" role="status" data-strokes>Draw a signature to begin.</p><form><div class="form-grid">'+[text('ink','Ink color','#213d33','color'),num('width','Stroke width',4,1,12,1),sel('background','Background',[['transparent','Transparent'],['white','White']],'transparent'),num('padding','Crop padding (px)',20,0,80,1)].map(field).join('')+'</div><div class="form-actions"><button type="submit" class="btn primary">Create signature PNG</button><button type="button" class="btn secondary" data-undo>Undo stroke</button><button type="button" class="btn secondary" data-clear>Clear drawing</button></div><div class="form-error"></div></form><p class="form-note">A drawn image is not a certificate-backed digital signature. Verify the recipient’s requirements.</p>';const c=mount.querySelector('canvas'),ctx=c.getContext('2d'),f=mount.querySelector('form'),status=mount.querySelector('[data-strokes]');function redraw(){ctx.clearRect(0,0,c.width,c.height);for(const s of strokes){ctx.strokeStyle=ctx.fillStyle=s.color;ctx.lineWidth=s.width;ctx.lineJoin=ctx.lineCap='round';ctx.beginPath();ctx.moveTo(s.points[0].x,s.points[0].y);s.points.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));if(s.points.length===1){ctx.arc(s.points[0].x,s.points[0].y,s.width/2,0,Math.PI*2);ctx.fill();}else ctx.stroke();}status.textContent=strokes.length+' stroke'+(strokes.length===1?'':'s')+' in this drawing.';}
 const point=ev=>{const r=c.getBoundingClientRect();return {x:Math.max(0,Math.min(c.width,(ev.clientX-r.left)/r.width*c.width)),y:Math.max(0,Math.min(c.height,(ev.clientY-r.top)/r.height*c.height))};};c.onpointerdown=ev=>{ev.preventDefault();if(strokes.length>=100)return;c.setPointerCapture(ev.pointerId);current={points:[point(ev)],color:f.elements.ink.value,width:+f.elements.width.value};strokes.push(current);redraw();};c.onpointermove=ev=>{if(!current||current.points.length>=3000)return;current.points.push(point(ev));redraw();};c.onpointerup=c.onpointercancel=()=>current=null;mount.querySelector('[data-undo]').onclick=()=>{strokes.pop();redraw();};mount.querySelector('[data-clear]').onclick=()=>{strokes=[];current=null;redraw();release();out.innerHTML='<div class="result-placeholder">Draw another signature to begin.</div>';};f.onsubmit=async ev=>{ev.preventDefault();try{need(strokes.length,'Draw at least one stroke.');const pad=+f.elements.padding.value+8,points=strokes.flatMap(s=>s.points),left=Math.max(0,Math.floor(points.reduce((v,p)=>Math.min(v,p.x),c.width)-pad)),top=Math.max(0,Math.floor(points.reduce((v,p)=>Math.min(v,p.y),c.height)-pad)),right=Math.min(c.width,Math.ceil(points.reduce((v,p)=>Math.max(v,p.x),0)+pad)),bottom=Math.min(c.height,Math.ceil(points.reduce((v,p)=>Math.max(v,p.y),0)+pad)),output=canvas(Math.max(1,right-left),Math.max(1,bottom-top)),x=output.getContext('2d');if(f.elements.background.value==='white'){x.fillStyle='white';x.fillRect(0,0,output.width,output.height);}x.drawImage(c,left,top,output.width,output.height,0,0,output.width,output.height);const blob=await canvasBlob(output);release();release=fileResult(out,blob,'nepocore-drawn-signature.png',{image:true,details:[['Dimensions',output.width+' × '+output.height+' px'],['Background',f.elements.background.value]]});}catch(ex){error(f.querySelector('.form-error'),ex.message);}};return()=>release();}
function textPoster(mount,out){return form(mount,[{...text('words','Your short text','MAKE IT','text',true),required:true},sel('font','Letter style',[['Arial','Modern sans'],['Georgia','Classic serif'],['monospace','Monospace']],'Arial'),num('depth','Shadow layers',14,1,30,1),text('front','Letter color','#f7efda','color'),text('side','Depth color','#386b5b','color'),text('background','Background','#e8f0e8','color')],v=>{need(Array.from(v.words).length<=24,'Use up to 24 characters.');const font=['Arial','Georgia','monospace'].includes(v.font)?v.font:'Arial',size=Math.min(170,760/(Math.max(1,Array.from(v.words).length)*.65)),layers=Array.from({length:+v.depth},(_,i)=>+v.depth-i).map(i=>`<text x="${450+i*2}" y="${300+i*2}" fill="${e(v.side)}">${e(v.words)}</text>`).join(''),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="560" viewBox="0 0 900 560" role="img" aria-label="Layered text poster"><rect width="900" height="560" fill="${e(v.background)}"/><g text-anchor="middle" font-family="${font}" font-weight="900" font-size="${size}">${layers}<text x="450" y="300" fill="${e(v.front)}" stroke="${e(v.side)}" stroke-width="1">${e(v.words)}</text></g></svg>`;vectorResult(out,svg,'nepocore-3d-text',{width:1800,height:1120,note:'Layered vector text, not a 3D model. Font substitution can change the appearance on another device.'});},{label:'Create text poster'});}
